input.command:
mkdir -p .lawcheck/rules && cat > .lawcheck/rules/no-fetch.mjs <<'EOF'
export async function check({ files }) {
  const findings = [];
  for (const file of files) {
    const { root } = await file.tree();
    if (root === null) continue;
    const stack = [root];
    while (stack.length > 0) {
      const node = stack.pop();
      const callee = node.type === 'call_expression' ? node.children.find((child) => child.field === 'function') : undefined;
      if (callee && file.text.slice(callee.start, callee.end) === 'fetch') findings.push({ line: node.line, message: 'calls fetch in core' });
      stack.push(...node.children);
    }
  }
  return findings;
}
EOF
python3 - <<'EOF'
p='.lawcheck/law.yaml'
s=open(p).read()
s=s.replace("\ntypes:","\nrules:\n  no-fetch:\n    why: Core does no network calls; only the api layer talks to the network.\n\ntypes:",1)
s=s.replace("    may_use: [core]","    may_use: [core]\n    rules: [no-fetch]")
open(p,'w').write(s)
EOF
lawcheck try no-fetch; lawcheck check --full

